// Configure the first row to inspect and the max number per run.
const START_ROW = 2;
const Max_Run = 10;

return $input.all()
  .filter(({ json: row }) => {
    const rowNumber = Number(row.row_number);
    const verdict = String(row.Verdict ?? '').trim().toLowerCase();
    const link = String(row['Proposal Link'] ?? '').trim();
    return rowNumber >= START_ROW &&
      (verdict === '' || verdict === 'pending') && link !== '';
  })
  .sort((a, b) => Number(a.json.row_number) - Number(b.json.row_number))
  .slice(0, Max_Run);

const row = $input.item.json;
const link = String(row['Proposal Link'] ?? '').trim();
const match = link.match(/\/d\/([a-zA-Z0-9_-]+)|[?&]id=([a-zA-Z0-9_-]+)/);
if (!match) throw new Error(`Cannot parse Google Drive file ID from proposal link (row ${row.row_number}).`);
return { json: { ...row, fileId: match[1] || match[2], proposalLink: link } };

const extracted = $input.item.json;
const original = $('05 - Parse Drive File ID').item.json;
const proposalText = String(extracted.text ?? '').trim();

// Image-only PDFs need OCR. Skip them instead of sending empty text to AI.
if (proposalText.length < 100) {
  throw new Error(`PDF has insufficient extractable text (row ${original.row_number}). OCR or manual review is needed.`);
}

return {
  json: {
    row_number: original.row_number,
    email: original['Email'],
    fullName: original['Full Name'],
    participantId: original['Participant ID'],
    event: original['Event'] ?? '',
    fileId: original.fileId,
    proposalLink: original.proposalLink,
    proposalText,
    extractionStatus: 'Ready'
  }
};

const submission = $('08 - Prepare Proposal Data').first().json;
const master = $input.item.json;
const warnings = [];
const normalize = value => String(value ?? '').trim().replace(/\s+/g, ' ').toLowerCase();
const masterFound = normalize(master.Email) !== '' &&
  normalize(master.Email) === normalize(submission.email);

if (!masterFound) {
  warnings.push('Participant email was not found in the reference database.');
} else {
  if (normalize(master['Participant ID']) !== normalize(submission.participantId)) {
    warnings.push('Participant ID does not match the reference database.');
  }
  if (normalize(master['Full Name']) !== normalize(submission.fullName)) {
    warnings.push('Participant name does not match the reference database.');
  }
}

return {
  json: {
    ...submission,
    masterRecordFound: masterFound,
    masterParticipantId: master['Participant ID'] ?? '',
    masterFullName: master['Full Name'] ?? '',
    masterEmail: master.Email ?? '',
    identityWarnings: warnings,
    identityStatus: warnings.length ? 'Warning' : 'Matched'
  }
};

const input = $input.item.json;
const original = $('10 - Verify Data Identity').item.json;
const issues = [];
const warnings = [...(original.identityWarnings || [])];

const raw = input.content?.parts?.filter(p => typeof p.text === 'string')
  .map(p => p.text).join('\n') ?? '';

function needsReview(reason) {
  return { json: { ...original, validationStatus: 'NeedsReview',
    issues: [], warnings, verdict: null, feedback: reason, shouldUpdate: false } };
}

let ai;
try {
  ai = JSON.parse(String(raw).replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/i, '').trim());
} catch (error) {
  return needsReview('AI response is not valid JSON.');
}

const required = ['participantCount', 'durationMinutes',
  'studentAudience', 'multipleEvents', 'needsReview'];
if (required.some(key => !(key in ai))) {
  return needsReview('AI response is missing required fields.');
}
if (ai.needsReview !== false) {
  return needsReview(ai.reviewReason || 'Manual review is required.');
}
if (!Number.isInteger(ai.participantCount) || ai.participantCount < 0 ||
    typeof ai.durationMinutes !== 'number' || !Number.isFinite(ai.durationMinutes) ||
    ai.durationMinutes < 0 || typeof ai.studentAudience !== 'boolean' ||
    typeof ai.multipleEvents !== 'boolean') {
  return needsReview('Required participant, duration, or event details are uncertain.');
}

// Customizable policy: change the thresholds and conditions here.
if (ai.participantCount < 10) issues.push(`Expected attendees: ${ai.participantCount} (minimum 10).`);
if (ai.durationMinutes < 30) issues.push(`Event duration: ${ai.durationMinutes} minutes (minimum 30).`);
if (!ai.studentAudience) issues.push('Primary audience is not students.');
if (ai.multipleEvents) issues.push('Proposal describes multiple separate events.');

const tools = Array.isArray(ai.thirdPartyToolsUsed) ? ai.thirdPartyToolsUsed : [];
if (tools.length) warnings.push(`Additional tools mentioned: ${tools.join(', ')}.`);

return { json: { ...original, aiAnalysis: ai,
  participantCount: ai.participantCount, durationMinutes: ai.durationMinutes,
  validationStatus: 'Completed', issues, warnings,
  verdict: issues.length ? 'Invalid' : 'Valid',
  feedback: [...issues, ...warnings].join('; '), shouldUpdate: true } };

const data = $input.item.json;

const issues = Array.isArray(data.issues)
  ? data.issues
  : [];

const warnings = Array.isArray(data.warnings)
  ? data.warnings
  : [];

if (data.validationStatus !== "Completed") {
  return {
    json: {
      ...data,
      shouldUpdate: false,
      finalVerdict: null,
      finalFeedback: "",
      skipReason: data.feedback ||
        "Manual review is required."
    }
  };
}

const finalVerdict = issues.length > 0
  ? "Invalid"
  : "Valid";

const messages = [...new Set([
  ...issues,
  ...warnings
])];

let finalFeedback = messages
  .slice(0, 2)
  .join("; ");

if (finalFeedback.length > 200) {
  finalFeedback = finalFeedback
    .slice(0, 197)
    .replace(/\s+\S*$/, "")
    .trim() + "...";
}

return {
  json: {
    ...data,
    shouldUpdate: true,
    finalVerdict,
    finalFeedback
  }
};

const target = $('13 - Format Validation Result').first().json;
const rows = $input.all().map(item => item.json);
const current = rows.find(row => Number(row.row_number) === Number(target.row_number));

if (!current) {
  return [{ json: { row_number: target.row_number, shouldWrite: false,
    skipReason: 'Current spreadsheet row was not found.' } }];
}

const currentVerdict = String(current.Verdict ?? '').trim().toLowerCase();
const shouldWrite = currentVerdict === '' || currentVerdict === 'pending';

return [{ json: {
  row_number: target.row_number,
  Verdict: target.finalVerdict,
  Feedback: target.finalFeedback,
  shouldWrite,
  skipReason: shouldWrite ? '' : 'Row already has a final verdict.'
} }];
